  { name:"Gina", film:"Porco Rosso (1992)", image:IMG("Gina"), desc:"Cantante y dueña del Hotel Adriano, viuda de tres pilotos. Elegancia serena y melancolía contenida: cantas la vida con dignidad.", quote:"El Adriático guarda mis canciones.", vector:[0.9,0.6,0.8,0.6,0.7,0.85,0.75,0.9,0.6,0.6] },
  { name:"Donald Curtis", film:"Porco Rosso (1992)", image:IMG("Curtis"), desc:"Piloto americano contratado por los piratas del aire, rival de Porco. Tu ambición y carisma esconden una búsqueda desesperada de aprobación.", quote:"¡Soy el mejor piloto del mundo, y eso es un hecho!", vector:[0.55,0.4,0.85,0.75,0.4,0.6,0.9,0.4,0.65,0.75] },
  { name:"El jefe de los Mamma Aiuto", film:"Porco Rosso (1992)", image:IMG("Jefe Mamma Aiuto"), desc:"Capitán de la banda de piratas aéreos Mamma Aiuto. Tu honor de clan es más importante que cualquier rescate.", quote:"¡Los Mamma Aiuto no perdonamos una afrenta!", vector:[0.5,0.4,0.85,0.6,0.35,0.85,0.9,0.55,0.6,0.6] },
  { name:"Ferrarin", film:"Porco Rosso (1992)", image:IMG("Ferrarin"), desc:"Mayor de la Regia Aeronautica y antiguo compañero de escuadrilla de Marco. Representas la hermandad que sobrevive incluso al silencio.", quote:"El cielo recuerda a los que ya no vuelan.", vector:[0.75,0.5,0.8,0.6,0.5,0.9,0.75,0.8,0.55,0.5] },
  { name:"Piccolo", film:"Porco Rosso (1992)", image:IMG("Piccolo"), desc:"Mecánico de Milán, constructor del hidroavión de Porco y abuelo de Fio. Maestro del oficio y de la paciencia.", quote:"Un motor bien afinado canta.", vector:[0.85,0.5,0.85,0.7,0.5,0.9,0.75,0.9,0.8,0.3] },
  { name:"Las mujeres del taller Piccolo", film:"Porco Rosso (1992)", image:IMG("Mujeres taller"), desc:"Plantilla familiar del taller aeronáutico de Milán que reconstruye el hidroavión de Porco. Fuerza colectiva, risa y oficio.", quote:"¡Aquí ninguna se achanta!", vector:[0.8,0.5,0.9,0.75,0.55,0.9,0.8,0.75,0.8,0.3] },
  { name:"Las quince niñas del Mamma Aiuto", film:"Porco Rosso (1992)", image:IMG("Ninas Mamma Aiuto"), desc:"Alumnas de un club de natación secuestradas en el asalto que abre la película. Vivís la aventura como quien va de excursión.", quote:"(Cantos y risas desde el hidroavión.)", vector:[0.8,0.6,0.6,0.85,0.5,0.7,0.55,0.55,0.7,0.35] },

  // ─── 8. Puedo escuchar el mar (1993) ───
  { name:"Rikako Muto", film:"Puedo escuchar el mar (1993)", image:IMG("Rikako"), desc:"Alumna trasladada desde Tokio que descoloca a toda la clase. Detrás de tu dureza hay un anhelo profundo de pertenencia.", quote:"A veces quiero desaparecer y a veces quiero que me vean.", vector:[0.7,0.5,0.85,0.7,0.5,0.7,0.9,0.55,0.7,0.85] },
  { name:"Taku Morisaki", film:"Puedo escuchar el mar (1993)", image:IMG("Taku"), desc:"Universitario en Tokio que recuerda sus años de instituto en Kōchi. Aprendes a nombrar lo que sientes sin miedo a la ternura.", quote:"Hay cosas que solo se entienden mirando el mar.", vector:[0.8,0.6,0.7,0.75,0.5,0.8,0.75,0.65,0.7,0.6] },
  { name:"Akiko Shimizu", film:"Puedo escuchar el mar (1993)", image:IMG("Akiko"), desc:"Compañera de clase y cabecilla del grupo que se enfrenta a Rikako. Representas la dureza del grupo cuando teme lo distinto.", quote:"Si no encajas, es tu problema, no el nuestro.", vector:[0.4,0.4,0.7,0.6,0.4,0.6,0.75,0.5,0.5,0.75] },
  { name:"El padre de Rikako", film:"Puedo escuchar el mar (1993)", image:IMG("Padre Rikako"), desc:"Padre divorciado de Rikako, que se quedó viviendo en Tokio. En tu distancia se cuece buena parte del dolor de tu hija.", quote:"Las cosas en Tokio no eran tan simples...", vector:[0.5,0.4,0.7,0.6,0.4,0.55,0.85,0.5,0.5,0.75] },
  { name:"Okada", film:"Puedo escuchar el mar (1993)", image:IMG("Okada"), desc:"Antiguo novio de Rikako en Tokio. Tu presencia desordena lo que ella intenta olvidar.", quote:"(Una llamada que Rikako no coge.)", vector:[0.55,0.4,0.65,0.6,0.4,0.55,0.8,0.5,0.55,0.7] },
  { name:"Tadashi Yamao", film:"Puedo escuchar el mar (1993)", image:IMG("Tadashi"), desc:"Compañero de clase de Taku, corpulento y enamorado de Yumi Kohama. Tu lealtad torpe se gana el cariño de todos.", quote:"Yo a Yumi la cuido, aunque no me haga caso.", vector:[0.85,0.5,0.7,0.5,0.4,0.9,0.7,0.6,0.5,0.4] },
  { name:"Yumi Kohama", film:"Puedo escuchar el mar (1993)", image:IMG("Yumi"), desc:"Compañera de clase de Taku y única amiga de Rikako en el instituto. Tu empatía callada hace más de lo que parece.", quote:"A veces hay que escuchar sin juzgar.", vector:[0.9,0.5,0.7,0.65,0.5,0.9,0.65,0.75,0.6,0.4] },
  { name:"Yutaka Matsuno", film:"Puedo escuchar el mar (1993)", image:IMG("Yutaka"), desc:"El mejor amigo de Taku, delegado de clase y enamorado de Rikako. En tu discreción cabe una dignidad enorme.", quote:"(Deja pasar una oportunidad sin decir nada.)", vector:[0.85,0.5,0.7,0.6,0.5,0.9,0.65,0.7,0.55,0.5] },

  // ─── 9. Pompoko (1994) ───
  { name:"Shōkichi", film:"Pompoko (1994)", image:IMG("Shokichi"), desc:"Tanuki joven de las colinas de Tama, testigo y superviviente de toda la guerra. Luchas por tu hogar con creatividad y humor.", quote:"¡La magia de los tanukis está viva!", vector:[0.7,0.95,0.8,0.85,0.85,0.85,0.8,0.6,0.9,0.4] },
  { name:"Oroku", film:"Pompoko (1994)", image:IMG("Oroku"), desc:"Anciana del consejo de Tama y maestra de transformación de la vieja escuela. Tu visión larga y paciente protege el legado.", quote:"Los antiguos sabemos esperar el momento justo.", vector:[0.9,0.9,0.6,0.6,0.9,0.85,0.5,0.95,0.6,0.3] },
  { name:"Gonta", film:"Pompoko (1994)", image:IMG("Gonta"), desc:"Jefe de la facción violenta de los tanuki de Tama. Tu rabia es también una forma de amor por lo que se pierde.", quote:"¡Se defiende con uñas y dientes o no se defiende!", vector:[0.4,0.9,0.85,0.6,0.55,0.85,0.9,0.3,0.65,0.75] },
  { name:"Okiyo", film:"Pompoko (1994)", image:IMG("Okiyo"), desc:"Tanuki joven del clan de Tama, compañera de Shōkichi. Lealtad y frescura al servicio de la comunidad.", quote:"¡Yo también quiero transformarme!", vector:[0.85,0.85,0.7,0.85,0.75,0.9,0.65,0.7,0.85,0.3] },
  { name:"Ponkichi", film:"Pompoko (1994)", image:IMG("Ponkichi"), desc:"Tanuki joven, compañero de Shōkichi y última voz de la película. En tu mirada se despide todo un mundo.", quote:"Ya no quedan bosques como los de antes.", vector:[0.85,0.9,0.7,0.75,0.85,0.85,0.6,0.75,0.7,0.65] },
  { name:"Seizaemon", film:"Pompoko (1994)", image:IMG("Seizaemon"), desc:"Anciano del clan de Suzugamori y voz moderada de la asamblea. La prudencia como forma superior de valor.", quote:"Antes de luchar, escuchemos.", vector:[0.8,0.8,0.7,0.6,0.7,0.85,0.65,0.9,0.5,0.35] },
  { name:"Los tanuki de Tama", film:"Pompoko (1994)", image:IMG("Tanuki Tama"), desc:"Comunidad de tanuki de las colinas de Tama, protagonista colectiva de la película. En vosotros se ve la fuerza de un pueblo que resiste.", quote:"(Tambores y danzas bajo la luna.)", vector:[0.75,0.95,0.8,0.75,0.85,0.85,0.75,0.6,0.85,0.5] },
  { name:"Los tres maestros de Shikoku", film:"Pompoko (1994)", image:IMG("Maestros Shikoku"), desc:"Los tres grandes tanuki legendarios de Shikoku, llamados a salvar el monte de Tama. Sabiduría antigua al servicio del presente.", quote:"La transformación verdadera empieza en el espíritu.", vector:[0.8,0.9,0.75,0.7,0.95,0.85,0.6,0.85,0.75,0.3] },

  // ─── 10. Susurros del corazón (1995) ───
  { name:"Shizuku Tsukishima", film:"Susurros del corazón (1995)", image:IMG("Shizuku"), desc:"Estudiante de tercero de secundaria que decide escribir una novela en dos meses. Moldeas tu talento con dedicación e imaginación.", quote:"Tengo que escribir para descubrir quién soy.", vector:[0.8,0.5,0.75,0.95,0.6,0.8,0.85,0.6,0.95,0.5] },
  { name:"Seiji Amasawa", film:"Susurros del corazón (1995)", image:IMG("Seiji"), desc:"Compañero de instituto que quiere ser constructor de violines. Persigues tus sueños con la disciplina del artesano.", quote:"Quiero hacer violines que hablen por sí solos.", vector:[0.75,0.7,0.85,0.85,0.5,0.85,0.8,0.65,0.85,0.3] },
  { name:"Barón Humbert von Gikkingen", film:"Susurros del corazón (1995)", image:IMG("Baron"), desc:"Figura de un gato caballero que preside la tienda Chikyuya. Caballeroso, elegante, sabio y protector.", quote:"Siempre busca tu propia luz en las cosas pequeñas.", vector:[0.85,0.5,0.85,0.8,0.75,0.9,0.9,0.9,0.85,0.3] },
  { name:"Muta", film:"Susurros del corazón (1995)", image:IMG("Muta"), desc:"Gato gordo y gruñón que guía a las protagonistas hasta donde no querían ir. Tus desplantes esconden un corazón enorme.", quote:"No me gusta que me llamen gordo.", vector:[0.5,0.4,0.75,0.6,0.4,0.85,0.9,0.6,0.6,0.5] },
  { name:"Shiho Tsukishima", film:"Susurros del corazón (1995)", image:IMG("Shiho"), desc:"Hermana mayor de Shizuku, universitaria. Práctica y algo mandona, pero bajo el ruido hay cariño.", quote:"¡Deja de soñar y ponte a estudiar!", vector:[0.65,0.4,0.8,0.65,0.4,0.85,0.8,0.55,0.55,0.55] },
  { name:"Shiro Nishi", film:"Susurros del corazón (1995)", image:IMG("Shiro Nishi"), desc:"Anticuario, abuelo de Seiji y primer lector de la novela de Shizuku. Descubres tesoros donde otros ven baratijas.", quote:"Los objetos guardan las historias que los tocaron.", vector:[0.9,0.6,0.8,0.7,0.85,0.9,0.65,0.9,0.7,0.35] },
  { name:"Sugimura", film:"Susurros del corazón (1995)", image:IMG("Sugimura"), desc:"Compañero de clase de Shizuku y tercera base del equipo de béisbol. Tu sinceridad brusca esconde un corazón atento.", quote:"(Le lanza una mirada antes de batear.)", vector:[0.7,0.5,0.75,0.6,0.4,0.8,0.85,0.55,0.55,0.6] },
  { name:"Yuko Harada", film:"Susurros del corazón (1995)", image:IMG("Yuko"), desc:"Mejor amiga de Shizuku. Leal, risueña y siempre lista para escuchar. Representas la amistad que sostiene sueños ajenos.", quote:"Si escribes un libro, yo lo leo primero.", vector:[0.95,0.5,0.7,0.75,0.5,0.95,0.7,0.75,0.65,0.3] },

  // ─── 11. La princesa Mononoke (1997) ───
  { name:"San (Princesa Mononoke)", film:"La princesa Mononoke (1997)", image:IMG("San"), desc:"Humana criada por lobos que combate a los hombres de la fundición. Tu espíritu guerrero es incorruptible y luchas con pasión incansable.", quote:"Lucho por el bosque y por los seres que no tienen voz.", vector:[0.4,1.0,0.95,0.6,0.8,0.9,0.95,0.3,0.5,0.7] },
  { name:"Ashitaka", film:"La princesa Mononoke (1997)", image:IMG("Ashitaka"), desc:"Último príncipe de una aldea emishi, condenado por una maldición en el brazo derecho. Buscas ver con ojos limpios de odio y construir puentes.", quote:"Ver con ojos no nublados por el odio.", vector:[0.95,0.9,0.9,0.7,0.8,0.95,0.8,0.9,0.6,0.4] },
  { name:"Lady Eboshi", film:"La princesa Mononoke (1997)", image:IMG("Eboshi"), desc:"Señora de la Ciudad del Hierro, fabricante de armas de fuego. Construyes tu visión con firmeza, incluso cuando el precio es alto.", quote:"Yo también tengo gente a la que proteger.", vector:[0.5,0.3,0.95,0.75,0.4,0.7,0.9,0.5,0.8,0.85] },
  { name:"Jigo", film:"La princesa Mononoke (1997)", image:IMG("Jigo"), desc:"Monje mercenario al servicio del emperador, cazador de la cabeza del dios. Sabes navegar entre intereses sin perder la sonrisa.", quote:"Todo tiene un precio en este mundo.", vector:[0.5,0.4,0.7,0.7,0.6,0.6,0.85,0.7,0.6,0.8] },
  { name:"Kaya", film:"La princesa Mononoke (1997)", image:IMG("Kaya"), desc:"Chica de la aldea emishi que despide a Ashitaka. Tu amor sereno espera sin exigir y sostiene sin ataduras.", quote:"Vuelve cuando puedas, aunque no vuelvas.", vector:[0.9,0.75,0.75,0.6,0.65,0.9,0.6,0.85,0.55,0.45] },
  { name:"Kodama", film:"La princesa Mononoke (1997)", image:IMG("Kodama"), desc:"Pequeños espíritus blancos que indican la salud del bosque. Cuando aparecéis, el bosque está vivo.", quote:"(Golpeteo de cabezas que gira.)", vector:[0.7,1.0,0.7,0.85,0.95,0.8,0.7,0.85,0.85,0.2] },
  { name:"Moro", film:"La princesa Mononoke (1997)", image:IMG("Moro"), desc:"Diosa loba de trescientos años, madre adoptiva de San. Furia antigua y amor salvaje en el mismo corazón.", quote:"No te perdono, humano. Pero a San la he criado.", vector:[0.5,1.0,0.95,0.6,0.9,0.95,0.9,0.5,0.5,0.75] },
  { name:"Nago", film:"La princesa Mononoke (1997)", image:IMG("Nago"), desc:"Dios jabalí herido por una bala que se convierte en demonio y maldice a Ashitaka. El dolor transformado en cólera que destruye lo que toca.", quote:"¡Mi carne arde! ¡Humanos malditos!", vector:[0.3,0.9,0.85,0.4,0.55,0.7,0.9,0.2,0.4,0.9] },
  { name:"Okkoto", film:"La princesa Mononoke (1997)", image:IMG("Okkoto"), desc:"Dios jabalí ciego que dirige el último ataque de su especie. La dignidad de un pueblo que prefiere morir de pie.", quote:"Mis jabalíes no se rinden.", vector:[0.6,0.95,0.95,0.5,0.75,0.9,0.9,0.4,0.5,0.7] },
  { name:"Toki (mujer)", film:"La princesa Mononoke (1997)", image:IMG("Toki"), desc:"Cabecilla de las mujeres que trabajan los fuelles de la Ciudad del Hierro. Fuerza, humor y liderazgo entre el humo del taller.", quote:"¡Aquí se trabaja con lo que hay y se hace lo que se puede!", vector:[0.8,0.4,0.9,0.7,0.4,0.85,0.85,0.6,0.7,0.4] },
  { name:"Yakul", film:"La princesa Mononoke (1997)", image:IMG("Yakul"), desc:"Montura de Ashitaka, un alce rojo domesticado. Lealtad silenciosa que cruza montañas sin pedir nada.", quote:"(Bufido suave al oler a su jinete.)", vector:[0.8,0.95,0.85,0.6,0.6,0.95,0.7,0.85,0.4,0.3] },
  { name:"Didarabotchi", film:"La princesa Mononoke (1997)", image:IMG("Didarabotchi"), desc:"Forma nocturna del Espíritu del Bosque, un gigante translúcido del tamaño de una montaña. La naturaleza en su escala más sobrecogedora.", quote:"(Su paso hace temblar la tierra.)", vector:[0.5,1.0,0.85,0.5,0.95,0.7,0.85,0.8,0.6,0.4] },
  { name:"El Espíritu del Bosque", film:"La princesa Mononoke (1997)", image:IMG("Espiritu Bosque"), desc:"Dios del bosque que da y quita la vida con la misma indiferencia. En tu rostro se lee la serenidad de lo que no juzga.", quote:"(Su cabeza gira lentamente, sin expresión.)", vector:[0.5,1.0,0.7,0.6,1.0,0.6,0.85,0.95,0.6,0.5] },

  // ─── 12. Mis vecinos los Yamada (1999) ───
  { name:"La abuela Shige", film:"Mis vecinos los Yamada (1999)", image:IMG("Shige Yamada"), desc:"Matriarca cálida y firme, madre de Matsuko. Sostienes la armonía familiar con sabiduría y humor cotidiano.", quote:"En esta casa siempre hay sitio para uno más.", vector:[0.85,0.6,0.8,0.6,0.7,0.95,0.6,0.85,0.7,0.4] },
  { name:"Takashi Yamada", film:"Mis vecinos los Yamada (1999)", image:IMG("Takashi Yamada"), desc:"Padre de familia, oficinista y jefe nominal de la casa. Tu amor se expresa en presencia constante más que en discursos.", quote:"Voy a llegar a casa temprano hoy, lo prometo.", vector:[0.8,0.5,0.8,0.6,0.5,0.9,0.55,0.7,0.65,0.5] },
  { name:"Matsuko Yamada", film:"Mis vecinos los Yamada (1999)", image:IMG("Matsuko Yamada"), desc:"Madre de familia con muy pocas ganas de hacer de madre de familia. Honesta, gruñona y profundamente querida.", quote:"¡Que alguien apague ese hervidor!", vector:[0.7,0.5,0.8,0.6,0.45,0.9,0.7,0.5,0.6,0.65] },
  { name:"Noboru Yamada", film:"Mis vecinos los Yamada (1999)", image:IMG("Noboru Yamada"), desc:"Hijo mayor, estudiante de secundaria y el que acaba diciendo en voz alta lo que piensa la película.", quote:"Pues yo creo que ya está bien.", vector:[0.75,0.5,0.7,0.75,0.55,0.85,0.8,0.65,0.6,0.5] },
  { name:"Nonoko Yamada", film:"Mis vecinos los Yamada (1999)", image:IMG("Nonoko Yamada"), desc:"Hija pequeña de los Yamada y narradora del primer tramo. Travesura y ternura en estado puro.", quote:"¡Mamá, he encontrado un tesoro!", vector:[0.85,0.7,0.6,0.9,0.85,0.85,0.4,0.6,0.9,0.15] },
  { name:"Pochi", film:"Mis vecinos los Yamada (1999)", image:IMG("Pochi"), desc:"El perro de los Yamada, sexto miembro de la casa. Testigo silencioso de todas las pequeñas revoluciones familiares.", quote:"(Mueve la cola con filosofía.)", vector:[0.8,0.7,0.7,0.6,0.5,0.9,0.55,0.85,0.4,0.3] },

  // ─── 13. El viaje de Chihiro (2001) ───
  { name:"Chihiro", film:"El viaje de Chihiro (2001)", image:IMG("Chihiro"), desc:"Niña de diez años atrapada en una casa de baños para dioses. Tu verdadero poder radica en la madurez, la empatía y la resiliencia.", quote:"Una vez que conoces a alguien, nunca lo olvidas realmente.", vector:[0.9,0.6,0.95,0.8,0.85,0.9,0.7,0.7,0.7,0.5] },
  { name:"Haku", film:"El viaje de Chihiro (2001)", image:IMG("Haku"), desc:"Aprendiz de Yubaba y espíritu de un río desaparecido. Guardas una gran fortaleza interior y proteges a quienes amas a cualquier costo.", quote:"No mires atrás hasta que hayas cruzado el río.", vector:[0.8,0.85,0.85,0.7,0.95,0.95,0.7,0.8,0.7,0.6] },
  { name:"Sin-Cara (Kaonashi)", film:"El viaje de Chihiro (2001)", image:IMG("Sin Cara"), desc:"Espíritu vacío que engulle todo lo que le den y habla con la voz de lo que ha tragado. Sensible y en búsqueda de conexión sincera.", quote:"(El silencio que pide ser aceptado.)", vector:[0.6,0.3,0.4,0.6,0.8,0.5,0.4,0.4,0.5,1.0] },
  { name:"Yubaba", film:"El viaje de Chihiro (2001)", image:IMG("Yubaba"), desc:"Bruja dueña de la casa de baños y patrona de todos sus trabajadores. Tu firmeza protege un orden que solo tú comprendes del todo.", quote:"Aquí se trabaja o se convierte en cerdo.", vector:[0.4,0.3,0.85,0.6,0.7,0.5,0.9,0.5,0.7,0.85] },
  { name:"Zeniba", film:"El viaje de Chihiro (2001)", image:IMG("Zeniba"), desc:"Hermana gemela de Yubaba, bruja retirada en una casa junto a un pantano. Tu magia sana más de lo que parece a primera vista.", quote:"Lo que pasó, pasó. No lo olvides, pero sigue adelante.", vector:[0.75,0.7,0.85,0.7,0.9,0.8,0.9,0.85,0.8,0.3] },
  { name:"Kamaji", film:"El viaje de Chihiro (2001)", image:IMG("Kamaji"), desc:"Fogonero de la casa de baños, con seis brazos y mando sobre los duendes del hollín. Detrás de tu apariencia huraña late una lealtad silenciosa.", quote:"El carbón no se apaga solo, pequeña.", vector:[0.8,0.5,0.85,0.6,0.6,0.85,0.9,0.85,0.7,0.4] },
  { name:"Lin", film:"El viaje de Chihiro (2001)", image:IMG("Lin"), desc:"Empleada de la casa de baños y compañera de habitación de Chihiro. Ayudas a otros a crecer mientras buscas tu propio horizonte.", quote:"Algún día me iré a la costa, ya verás.", vector:[0.75,0.5,0.85,0.75,0.5,0.85,0.9,0.6,0.7,0.55] },
  { name:"Bôh", film:"El viaje de Chihiro (2001)", image:IMG("Boh"), desc:"Hijo gigante de Yubaba, encerrado en una habitación llena de almohadas. En tu encierro late un deseo inmenso de ver el mundo.", quote:"¡Si me haces llorar, mamá te castigará!", vector:[0.7,0.4,0.5,0.85,0.6,0.7,0.5,0.4,0.7,0.6] },
  { name:"El dios del río", film:"El viaje de Chihiro (2001)", image:IMG("Dios Rio"), desc:"Cliente irreconocible del balneario, cubierto de basura hasta que lo limpian. En ti se ve el dolor de lo que la humanidad ensucia.", quote:"(Un suspiro de alivio al ser limpiado.)", vector:[0.6,0.95,0.85,0.5,0.8,0.7,0.8,0.75,0.4,0.55] },
  { name:"Los padres de Chihiro", film:"El viaje de Chihiro (2001)", image:IMG("Padres Chihiro"), desc:"Matrimonio que se come la comida de los dioses y acaba en una pocilga. Encarnáis la tentación de lo que no nos pertenece.", quote:"(Gruñidos de cerdos en el comedor.)", vector:[0.4,0.3,0.5,0.5,0.3,0.6,0.7,0.4,0.4,0.7] },

  // ─── 14. Haru en el reino de los gatos (2002) ───
  { name:"Haru Yoshioka", film:"Haru en el reino de los gatos (2002)", image:IMG("Haru Yoshioka"), desc:"Estudiante de instituto que salva a un gato y recibe un agradecimiento que no quiere. Aprendes a decir «no» y a elegir tu propio destino.", quote:"¡Yo decido mi propia vida!", vector:[0.8,0.6,0.75,0.8,0.6,0.85,0.8,0.7,0.7,0.4] },
  { name:"Muta", film:"Haru en el reino de los gatos (2002)", image:IMG("Muta reino"), desc:"Gato grande, gruñón y leal, guía a Haru en el reino. Tus desplantes esconden un corazón enorme.", quote:"No me gusta que me llamen gordo.", vector:[0.5,0.4,0.75,0.6,0.4,0.85,0.9,0.6,0.6,0.5] },
  { name:"Yuki", film:"Haru en el reino de los gatos (2002)", image:IMG("Yuki"), desc:"Gata blanca del servicio de palacio y antigua conocida de Haru. Delicada y agradecida: guardas la memoria del cariño.", quote:"Los que nos ayudaron una vez, nunca se olvidan.", vector:[0.85,0.6,0.7,0.7,0.6,0.9,0.7,0.75,0.6,0.5] },
  { name:"Príncipe Lune", film:"Haru en el reino de los gatos (2002)", image:IMG("Principe Lune"), desc:"Heredero del Reino de los Gatos, el gato al que Haru salva. Nobleza amable que reconoce sus deudas.", quote:"Le debo la vida a esta humana.", vector:[0.85,0.6,0.8,0.7,0.7,0.9,0.75,0.8,0.6,0.35] },
  { name:"Rey Gato", film:"Haru en el reino de los gatos (2002)", image:IMG("Rey Gato"), desc:"Monarca del Reino de los Gatos y padre del príncipe Lune. Tu amor por tu hijo toma formas equivocadas.", quote:"¡Una humana será la nueva princesa!", vector:[0.5,0.4,0.85,0.6,0.7,0.8,0.9,0.55,0.6,0.65] },
  { name:"Natoru", film:"Haru en el reino de los gatos (2002)", image:IMG("Natoru"), desc:"Enviado del Rey Gato encargado de trasladar las invitaciones a Haru. Simpático, entusiasta y algo torpe.", quote:"¡Es una invitación del Rey, no se puede rechazar!", vector:[0.75,0.5,0.65,0.8,0.55,0.8,0.6,0.6,0.7,0.3] },
  { name:"Toto", film:"Haru en el reino de los gatos (2002)", image:IMG("Toto"), desc:"Cuervo de piedra que cobra vida y socio del Barón. En tu silencio hay una fidelidad de siglos.", quote:"(Un aleteo de piedra al amanecer.)", vector:[0.75,0.6,0.85,0.6,0.85,0.9,0.8,0.85,0.5,0.4] },

  // ─── 15. El castillo ambulante (2004) ───
  { name:"Howl Jenkins Pendragon", film:"El castillo ambulante (2004)", image:IMG("Howl"), desc:"Mago poderosísimo que vive huyendo y que le entregó su corazón a un demonio de fuego. Apasionado, dramático y profundamente talentoso.", quote:"Un corazón es una carga pesada de llevar.", vector:[0.7,0.5,0.6,0.9,0.85,0.8,0.85,0.4,0.95,0.8] },
  { name:"Sophie Hatter", film:"El castillo ambulante (2004)", image:IMG("Sophie"), desc:"Sombrerera de dieciocho años convertida en anciana y, sin saberlo, bruja. Descubres tu enorme fuerza interna a través del cuidado incondicional.", quote:"Dicen que el fuego más brillante quema más rápido.", vector:[0.95,0.6,0.9,0.6,0.7,0.95,0.75,0.9,0.8,0.4] },
  { name:"Calcifer", film:"El castillo ambulante (2004)", image:IMG("Calcifer"), desc:"Demonio de fuego que mueve el castillo y guarda el corazón de Howl. Aunque rezongues, tu calor sostiene el hogar.", quote:"¡A los demonios del fuego no nos impresiona nadie!", vector:[0.6,0.4,0.7,0.8,0.85,0.85,0.6,0.5,0.9,0.6] },
  { name:"Markl", film:"El castillo ambulante (2004)", image:IMG("Markl"), desc:"Aprendiz de Howl y encargado de atender a los clientes del castillo. Creces rápido porque observas con atención y corazón.", quote:"¡Ya sé lanzar el hechizo de la capa!", vector:[0.8,0.5,0.75,0.85,0.6,0.9,0.7,0.6,0.85,0.3] },
  { name:"Nabo", film:"El castillo ambulante (2004)", image:IMG("Nabo"), desc:"Espantapájaros embrujado que resulta ser el príncipe desaparecido. Presencia silenciosa y protectora: tu amor se demuestra en actos.", quote:"(Se inclina en silencio, fiel a quien lo salvó.)", vector:[0.7,0.6,0.75,0.5,0.7,0.85,0.6,0.85,0.5,0.5] },
  { name:"Madame Suliman", film:"El castillo ambulante (2004)", image:IMG("Suliman"), desc:"Maga real de Ingary, antigua maestra de Howl y responsable del esfuerzo de guerra. Enseñas a los demás a elegir con libertad.", quote:"Tú decides tu propio camino, no yo.", vector:[0.5,0.5,0.8,0.75,0.85,0.6,0.9,0.85,0.7,0.6] },
  { name:"Bruja del Páramo", film:"El castillo ambulante (2004)", image:IMG("Bruja Páramo"), desc:"Hechicera desterrada que maldice a Sophie y persigue el corazón de Howl. En tu obsesión por el poder late una soledad sin nombre.", quote:"¡Ese corazón será mío!", vector:[0.3,0.3,0.8,0.6,0.7,0.4,0.9,0.4,0.6,0.9] },
  { name:"Heen", film:"El castillo ambulante (2004)", image:IMG("Heen"), desc:"Perro de Suliman enviado a espiar a Sophie que acaba quedándose en el castillo. Pequeño, fiel y siempre en el lugar oportuno.", quote:"(Jadea sentado en la escalera del castillo.)", vector:[0.85,0.6,0.7,0.65,0.5,0.9,0.55,0.8,0.5,0.3] },

  // ─── 16. Cuentos de Terramar (2006) ───
  { name:"Arren", film:"Cuentos de Terramar (2006)", image:IMG("Arren"), desc:"Príncipe de Enlad, que mata a su padre en los primeros minutos y huye sin saber por qué. Tu viaje es mirar de frente lo que más temes.", quote:"Debo enfrentar lo que me persigue.", vector:[0.75,0.6,0.7,0.7,0.6,0.85,0.8,0.6,0.6,0.85] },
  { name:"Therru", film:"Cuentos de Terramar (2006)", image:IMG("Therru"), desc:"Chica con la cara quemada acogida por Tenar, la única que no teme morir. Tu fuego interior transforma el miedo en valentía.", quote:"El miedo no es lo mismo que la prudencia.", vector:[0.85,0.85,0.8,0.7,0.9,0.85,0.8,0.75,0.7,0.6] },
  { name:"Ged (Halcón)", film:"Cuentos de Terramar (2006)", image:IMG("Ged"), desc:"Archimago de Terramar, que recorre las tierras buscando qué ha roto el equilibrio del mundo. Sabiduría del que ha conocido su propia sombra.", quote:"Para sanar hay que nombrar lo que duele.", vector:[0.8,0.7,0.9,0.75,0.85,0.85,0.85,0.9,0.6,0.4] },
  { name:"Cob", film:"Cuentos de Terramar (2006)", image:IMG("Cob"), desc:"Mago que ha abierto una puerta entre la vida y la muerte para no morir nunca. En tu inmortalidad vive un miedo profundo.", quote:"La muerte es solo un cuento que los vivos no superan.", vector:[0.2,0.2,0.75,0.6,0.7,0.3,0.95,0.4,0.5,0.95] },
  { name:"Hare", film:"Cuentos de Terramar (2006)", image:IMG("Hare"), desc:"Jefe de los tratantes de esclavos de Hort Town y hombre de los recados de Cob. Astucia comercial al servicio de la sombra.", quote:"Todo lo que se mueve tiene un precio.", vector:[0.3,0.3,0.7,0.7,0.4,0.5,0.9,0.6,0.5,0.85] },
  { name:"Tenar", film:"Cuentos de Terramar (2006)", image:IMG("Tenar"), desc:"Granjera, vieja amiga de Ged y madre adoptiva de Therru. Tu fortaleza tranquila sostiene a quien ya no cree en nada.", quote:"Aquí tendrás un hogar mientras lo necesites.", vector:[0.95,0.8,0.85,0.65,0.7,0.9,0.7,0.85,0.55,0.4] },
  { name:"Los dragones de Terramar", film:"Cuentos de Terramar (2006)", image:IMG("Dragones Terramar"), desc:"Los dragones del archipiélago, que abren y cierran la película. Fuerza antigua que equilibra el mundo cuando el hombre olvida su lugar.", quote:"(El batir de alas en el horizonte.)", vector:[0.6,0.95,0.9,0.6,0.95,0.7,0.9,0.85,0.5,0.5] },

  // ─── 17. Ponyo en el acantilado (2008) ───
  { name:"Ponyo", film:"Ponyo en el acantilado (2008)", image:IMG("Ponyo"), desc:"Hija de un mago del mar y de la diosa del océano que decide convertirse en niña humana. Alegría pura, curiosidad y amor sin reservas.", quote:"¡Sōsuke! ¡Sōsuke!", vector:[0.9,0.95,0.85,0.95,0.9,0.9,0.75,0.7,0.95,0.25] },
  { name:"Sōsuke", film:"Ponyo en el acantilado (2008)", image:IMG("Sosuke"), desc:"Niño de cinco años que vive en la casa del acantilado y encuentra a Ponyo en la orilla. Tu amor es una promesa que sostienes con ternura firme.", quote:"Yo te protegeré, Ponyo.", vector:[0.9,0.75,0.8,0.85,0.7,0.95,0.75,0.75,0.8,0.2] },
  { name:"Fujimoto", film:"Ponyo en el acantilado (2008)", image:IMG("Fujimoto"), desc:"Antiguo humano convertido en mago del mar, padre de Ponyo y guardián del equilibrio marino. Amas con una intensidad que a veces asusta.", quote:"El mar está perdiendo su equilibrio.", vector:[0.6,0.95,0.75,0.7,0.7,0.7,0.85,0.6,0.75,0.6] },
  { name:"Lisa", film:"Ponyo en el acantilado (2008)", image:IMG("Lisa"), desc:"Madre de Sōsuke, auxiliar en la residencia Himawari y conductora temeraria. Tu franqueza y alegría llenan de vida cualquier hogar.", quote:"¡Aquí no se rinde nadie!", vector:[0.85,0.6,0.9,0.7,0.5,0.9,0.85,0.6,0.65,0.5] },
  { name:"Granmamare", film:"Ponyo en el acantilado (2008)", image:IMG("Granmamare"), desc:"Diosa del océano, madre de Ponyo y única autoridad capaz de deshacer el desastre. En ti habita la serenidad de lo que todo lo ve.", quote:"El océano también sabe amar, aunque a veces olvide cómo.", vector:[0.9,1.0,0.85,0.6,1.0,0.75,0.9,0.95,0.6,0.3] },
  { name:"Kōichi", film:"Ponyo en el acantilado (2008)", image:IMG("Koichi"), desc:"Capitán del carguero Koganei-maru y padre de Sōsuke. Tu ausencia enseña a tu hijo el valor de los compromisos.", quote:"Volveré cuando el mar me deje.", vector:[0.7,0.7,0.85,0.6,0.5,0.9,0.8,0.75,0.5,0.4] },
  { name:"Las hermanas de Ponyo", film:"Ponyo en el acantilado (2008)", image:IMG("Hermanas Ponyo"), desc:"Las casi cien hermanas menores de Ponyo. En vuestro cardumen se ve la belleza del movimiento colectivo.", quote:"(Nadan en perfecta sincronía.)", vector:[0.7,0.95,0.7,0.7,0.8,0.85,0.55,0.75,0.6,0.2] },
  { name:"La mujer del bebé", film:"Ponyo en el acantilado (2008)", image:IMG("Mujer bebe"), desc:"Madre joven a la que Sōsuke y Ponyo encuentran en el pueblo inundado. Tu fragilidad es también una fortaleza silenciosa.", quote:"Gracias por ayudar, niños.", vector:[0.9,0.6,0.75,0.6,0.5,0.85,0.6,0.8,0.5,0.55] },
  { name:"Toki (anciana)", film:"Ponyo en el acantilado (2008)", image:IMG("Toki Ponyo"), desc:"Anciana en silla de ruedas de la residencia Himawari, desconfiada con Ponyo y con casi todo. Bajo tu dureza hay una ternura intacta.", quote:"No me fío de lo que viene del mar.", vector:[0.6,0.5,0.75,0.5,0.6,0.7,0.85,0.7,0.4,0.7] },
  { name:"Yoshie, Kayo y Toki", film:"Ponyo en el acantilado (2008)", image:IMG("Yoshie Kayo Toki"), desc:"Residentes del centro de día donde trabaja Lisa. En vuestra alegría renovada se ve la promesa del reencuentro.", quote:"¡Volvemos a caminar!", vector:[0.85,0.7,0.8,0.65,0.7,0.9,0.6,0.8,0.55,0.45] },

  // ─── 18. Arrietty y el mundo de los diminutos (2010) ───
  { name:"Arrietty", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Arrietty"), desc:"Joven de la familia de diminutos que vive bajo el suelo de una casa de Koganei. Defiendes tu independencia sin renunciar a la ternura.", quote:"Los diminutos también tenemos nuestro orgullo.", vector:[0.85,0.7,0.9,0.85,0.6,0.9,0.9,0.7,0.8,0.4] },
  { name:"Shō", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Sho"), desc:"Chico enfermo del corazón que pasa unos días en la casa de su tía abuela. Tu mirada atenta descubre la belleza en lo diminuto.", quote:"Me alegra haberte conocido, Arrietty.", vector:[0.9,0.75,0.6,0.8,0.7,0.85,0.7,0.8,0.7,0.7] },
  { name:"Spiller", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Spiller"), desc:"Diminuto cazador que vive fuera de las casas humanas. Silencioso y leal: prefieres demostrar el cariño con hechos discretos.", quote:"(Te ofrece una baya en silencio.)", vector:[0.6,0.8,0.85,0.6,0.5,0.75,0.9,0.7,0.55,0.6] },
  { name:"Homily", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Homily"), desc:"Madre de Arrietty, encargada de la casa bajo el suelo. Tu ternura nerviosa y constante hace habitable cada rincón.", quote:"¡Que no se lleve nada de nuestra casa!", vector:[0.9,0.6,0.75,0.55,0.5,0.9,0.6,0.7,0.65,0.6] },
  { name:"Pod", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Pod"), desc:"Padre de Arrietty y encargado de las expediciones para tomar prestado. Prudencia silenciosa y saber transmitido con el ejemplo.", quote:"Para tomar prestado, primero hay que saber observar.", vector:[0.8,0.7,0.9,0.7,0.55,0.9,0.85,0.85,0.6,0.3] },
  { name:"Haru (ama de llaves)", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Haru ama"), desc:"Ama de llaves de la casa, decidida a demostrar que los diminutos existen. Tu obsesión nace del miedo a lo que no entiendes.", quote:"¡Ya verás como existen, ya lo verás!", vector:[0.3,0.4,0.85,0.7,0.4,0.5,0.9,0.4,0.5,0.85] },
  { name:"Niya", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Niya"), desc:"Gato de la casa de los Maki. Curiosidad felina y lealtad de otra especie al servicio de los diminutos.", quote:"(Un miau curioso bajo la mesa.)", vector:[0.7,0.7,0.7,0.75,0.5,0.8,0.7,0.85,0.5,0.3] },
  { name:"Sadako Maki", film:"Arrietty y el mundo de los diminutos (2010)", image:IMG("Sadako"), desc:"Tía abuela de Shō y dueña de la casa. Memoria viva de una familia y guardiana de secretos del jardín.", quote:"De niña también oí algo bajo el suelo.", vector:[0.9,0.75,0.7,0.6,0.75,0.9,0.6,0.9,0.55,0.45] },

  // ─── 19. La colina de las amapolas (2011) ───
  { name:"Umi Matsuzaki", film:"La colina de las amapolas (2011)", image:IMG("Umi"), desc:"Estudiante que lleva una pensión en Yokohama y iza banderas de señales cada mañana. Sostienes a los tuyos mientras abres camino a tus sueños.", quote:"El mar siempre me devuelve la calma.", vector:[0.85,0.6,0.85,0.7,0.6,0.9,0.85,0.7,0.75,0.5] },
  { name:"Shun Kazama", film:"La colina de las amapolas (2011)", image:IMG("Shun"), desc:"Estudiante del periódico escolar y cabecilla de la defensa del Quartier Latin. Defiendes lo que amas con una entereza serena.", quote:"Hay cosas que merecen pelearse.", vector:[0.85,0.65,0.8,0.7,0.7,0.9,0.8,0.75,0.7,0.55] },
  { name:"Hana Matsuzaki", film:"La colina de las amapolas (2011)", image:IMG("Hana"), desc:"Abuela de Umi y propietaria de la pensión Coquelicot. Sabiduría discreta que sostiene a tres generaciones.", quote:"Las banderas anuncian que la casa está viva.", vector:[0.9,0.6,0.8,0.6,0.6,0.95,0.65,0.85,0.55,0.4] },
  { name:"Ryoko Matsuzaki", film:"La colina de las amapolas (2011)", image:IMG("Ryoko"), desc:"Madre de Umi, profesora universitaria de vuelta de Estados Unidos. Tu ausencia enseña autonomía a tus hijas.", quote:"Volveré cuando termine el curso.", vector:[0.8,0.5,0.85,0.75,0.5,0.85,0.85,0.7,0.65,0.5] },
  { name:"Sora Matsuzaki", film:"La colina de las amapolas (2011)", image:IMG("Sora"), desc:"Hermana pequeña de Umi, alumna de primero en el mismo instituto. Alegría y franqueza adolescente al servicio de los suyos.", quote:"¡Voy a izar la bandera yo sola hoy!", vector:[0.85,0.6,0.7,0.8,0.55,0.9,0.7,0.6,0.7,0.35] },
  { name:"Akio Kazama", film:"La colina de las amapolas (2011)", image:IMG("Akio"), desc:"Patrón de remolcadores en el puerto de Yokohama y padre adoptivo de Shun. Tu amor tiene forma de trabajo y constancia.", quote:"Un hombre vale por lo que sostiene.", vector:[0.85,0.5,0.9,0.6,0.5,0.9,0.85,0.75,0.55,0.4] },
  { name:"Mizunuma", film:"La colina de las amapolas (2011)", image:IMG("Mizunuma"), desc:"Presidente del consejo estudiantil y estratega de la campaña del Barrio Latino. Inteligencia al servicio de la comunidad.", quote:"¡Salvemos el Quartier Latin!", vector:[0.75,0.4,0.85,0.85,0.5,0.85,0.8,0.6,0.75,0.4] },
  { name:"Tokumaru", film:"La colina de las amapolas (2011)", image:IMG("Tokumaru"), desc:"Presidente del patronato del instituto Kōnan y dueño de una editorial en Tokio. En tu poder se prueba la tentación de comprar la memoria.", quote:"Todo se puede negociar, muchachos.", vector:[0.4,0.3,0.85,0.7,0.4,0.5,0.9,0.55,0.6,0.8] },
  { name:"Yoshio Onodera", film:"La colina de las amapolas (2011)", image:IMG("Onodera"), desc:"Antiguo compañero de barco del padre de Umi, ahora en una naviera de Tokio. La memoria del mar que sigue uniendo generaciones.", quote:"Tu padre era el mejor marino que he conocido.", vector:[0.8,0.7,0.75,0.6,0.55,0.9,0.7,0.8,0.5,0.4] },

  // ─── 20. El viento se levanta (2013) ───
  { name:"Jirō Horikoshi", film:"El viento se levanta (2013)", image:IMG("Jiro"), desc:"Ingeniero aeronáutico, diseñador de los cazas de Mitsubishi. Tu pasión por la belleza y la excelencia técnica guía tu destino.", quote:"El viento se levanta... ¡debemos intentar vivir!", vector:[0.7,0.6,0.85,0.95,0.6,0.8,0.85,0.8,1.0,0.6] },
  { name:"Naoko Satomi", film:"El viento se levanta (2013)", image:IMG("Naoko"), desc:"Pintora, enferma de tuberculosis y esposa de Jirō. Delicada, profunda y valiente: amas sin reservas y eliges la belleza aunque duela.", quote:"Quiero vivir contigo cada momento que me quede.", vector:[0.9,0.7,0.6,0.7,0.8,0.9,0.6,0.85,0.75,0.8] },
  { name:"Caproni", film:"El viento se levanta (2013)", image:IMG("Caproni"), desc:"Ingeniero italiano que se aparece a Jirō en sueños. Mentor visionario: inspiras a otros a soñar más allá de lo posible.", quote:"Los diseñadores soñamos con alas.", vector:[0.75,0.5,0.8,0.85,0.6,0.85,0.85,0.8,0.9,0.35] },
  { name:"Hans Castorp", film:"El viento se levanta (2013)", image:IMG("Hans Castorp"), desc:"Huésped alemán del hotel de Karuizawa. En tu mirada extranjera se refleja el mundo que se desmorona.", quote:"Europa está a punto de romperse, y nadie lo detendrá.", vector:[0.55,0.5,0.6,0.75,0.6,0.6,0.8,0.6,0.65,0.7] },
  { name:"Honjō", film:"El viento se levanta (2013)", image:IMG("Honjo"), desc:"Compañero de estudios y de Mitsubishi, diseñador de bombarderos. Amistad profesional forjada en la pasión común.", quote:"Tú haces cazas, yo bombarderos... alguien tiene que hacerlo.", vector:[0.7,0.5,0.85,0.85,0.5,0.85,0.75,0.7,0.8,0.5] },
  { name:"Kayo Horikoshi", film:"El viento se levanta (2013)", image:IMG("Kayo"), desc:"Hermana menor de Jirō, estudiante y después médica. Tu franqueza cariñosa es el contrapunto vital de tu hermano.", quote:"¡Hermano, deja de pensar en aviones un rato!", vector:[0.85,0.5,0.85,0.7,0.5,0.9,0.85,0.6,0.6,0.4] },
  { name:"Kurokawa", film:"El viento se levanta (2013)", image:IMG("Kurokawa"), desc:"Superior de Jirō en Mitsubishi y anfitrión de su matrimonio. Disciplina y afecto escondido bajo la formalidad.", quote:"Un buen ingeniero es un soldado del cielo.", vector:[0.6,0.4,0.9,0.7,0.5,0.85,0.85,0.65,0.7,0.55] },

  // ─── 21. El cuento de la princesa Kaguya (2013) ───
  { name:"Kaguya", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Kaguya"), desc:"Niña encontrada dentro de un tallo de bambú y criada como princesa contra su voluntad. Amas la belleza efímera de la vida y la naturaleza libre.", quote:"Nací para vivir de verdad, para sentir la hierba y el viento.", vector:[0.85,0.95,0.6,0.9,0.9,0.7,0.9,0.5,0.9,0.8] },
  { name:"El cortador de bambú", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Cortador bambu"), desc:"Padre adoptivo de Kaguya, convencido de que la felicidad de su hija es un título nobiliario. Tu amor toma la forma equivocada.", quote:"¡Mi hija será una dama de la corte!", vector:[0.6,0.5,0.75,0.5,0.6,0.9,0.7,0.55,0.5,0.55] },
  { name:"Ōna", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Ona"), desc:"Madre adoptiva de Kaguya, la única adulta que la escucha. Amor incondicional que no necesita títulos ni palacios.", quote:"Mi niña es mi niña, sea quien sea.", vector:[0.95,0.85,0.8,0.6,0.7,0.95,0.55,0.85,0.6,0.4] },
  { name:"La dama Sagami", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Sagami"), desc:"Institutriz contratada para convertir a Kaguya en una dama de la corte. Tu idea del deber choca con la libertad de otra.", quote:"Una dama no corre por el jardín.", vector:[0.5,0.4,0.85,0.5,0.5,0.7,0.8,0.7,0.5,0.5] },
  { name:"Me no Warawa", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Warawa"), desc:"Criada de la edad de Kaguya, su única compañía en la mansión. Amistad sencilla que sostiene en el encierro.", quote:"(Ríe con Kaguya como dos niñas.)", vector:[0.9,0.7,0.7,0.75,0.6,0.95,0.5,0.75,0.6,0.5] },
  { name:"El Mikado", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Mikado"), desc:"Emperador de Japón, último pretendiente de Kaguya. Poder que no concibe un «no».", quote:"Nadie rechaza al Emperador.", vector:[0.3,0.3,0.85,0.55,0.6,0.6,0.9,0.55,0.5,0.75] },
  { name:"Los cinco pretendientes", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Pretendientes"), desc:"Cinco nobles que piden la mano de Kaguya y reciben cinco encargos imposibles. La nobleza reducida a su ambición.", quote:"Traeré lo que me pidas, aunque sea imposible.", vector:[0.4,0.3,0.75,0.6,0.5,0.5,0.9,0.5,0.5,0.7] },
  { name:"Sutemaru", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Sutemaru"), desc:"El chico mayor de la cuadrilla del monte, primer y único afecto de Kaguya. Amor sencillo y libre de ataduras.", quote:"(Le silba una melodía desde lo alto del árbol.)", vector:[0.8,0.85,0.7,0.8,0.7,0.85,0.85,0.75,0.7,0.5] },
  { name:"Los celestiales de la Luna", film:"El cuento de la princesa Kaguya (2013)", image:IMG("Celestiales"), desc:"Cortejo del reino lunar que baja a recuperar a Kaguya. En vuestra serenidad perfecta late una tristeza sin nombre.", quote:"Has de volver, Kaguya. Tu lugar no es este mundo.", vector:[0.5,0.6,0.75,0.55,0.95,0.6,0.9,0.95,0.5,0.7] },

  // ─── 22. El recuerdo de Marnie (2014) ───
  { name:"Anna Sasaki", film:"El recuerdo de Marnie (2014)", image:IMG("Anna"), desc:"Adolescente adoptada y asmática que pasa un verano en la costa de Hokkaido. Tu sensibilidad te permite reconocer el dolor ajeno y sanarlo.", quote:"A veces me pregunto si merezco ser feliz.", vector:[0.9,0.7,0.65,0.8,0.85,0.9,0.55,0.65,0.85,0.85] },
  { name:"Marnie", film:"El recuerdo de Marnie (2014)", image:IMG("Marnie"), desc:"La chica rubia de la casa de la marisma. Misteriosa, cariñosa y nostálgica: tu presencia sana heridas del pasado.", quote:"Prométeme que mantendrás nuestro secreto por siempre.", vector:[0.9,0.7,0.5,0.8,0.9,0.9,0.5,0.7,0.8,0.85] },
  { name:"El aya", film:"El recuerdo de Marnie (2014)", image:IMG("Aya"), desc:"Ama de llaves de la mansión de la marisma, encargada de criar a Marnie. En tu silencio se sostiene una casa entera.", quote:"La señorita Marnie no sale de su habitación.", vector:[0.7,0.5,0.7,0.55,0.6,0.9,0.75,0.85,0.4,0.6] },
  { name:"Hisako", film:"El recuerdo de Marnie (2014)", image:IMG("Hisako"), desc:"Pintora del pueblo que conoció a Marnie de niña. Memoria y pincel al servicio de la verdad.", quote:"La conocí cuando éramos niñas.", vector:[0.85,0.7,0.75,0.75,0.6,0.9,0.7,0.85,0.8,0.45] },
  { name:"Kazuhiko", film:"El recuerdo de Marnie (2014)", image:IMG("Kazuhiko"), desc:"Amigo de infancia de Marnie, después su marido, y abuelo de Anna. Amor sereno que atraviesa generaciones.", quote:"Hay amores que no se olvidan nunca.", vector:[0.9,0.7,0.75,0.6,0.7,0.95,0.65,0.85,0.6,0.6] },
  { name:"Nobuko", film:"El recuerdo de Marnie (2014)", image:IMG("Nobuko"), desc:"Chica del pueblo, delegada de su clase, a la que Anna insulta en el festival. Tu generosidad final demuestra que no guardas rencor.", quote:"¡Todos los del pueblo estamos igual!", vector:[0.75,0.6,0.75,0.65,0.5,0.85,0.7,0.65,0.6,0.4] },
  { name:"Sayaka", film:"El recuerdo de Marnie (2014)", image:IMG("Sayaka"), desc:"Niña que se muda a la casa de la marisma y encuentra el diario de Marnie. Curiosidad luminosa que abre puertas cerradas.", quote:"(Abre el diario con cuidado.)", vector:[0.8,0.6,0.65,0.9,0.6,0.8,0.75,0.7,0.7,0.35] },
  { name:"Toichi", film:"El recuerdo de Marnie (2014)", image:IMG("Toichi"), desc:"Pescador anciano del pueblo, dueño de la barca amarrada en la marisma. Sabiduría de mar y silencio de siglos.", quote:"La marisma guarda muchas historias.", vector:[0.85,0.85,0.7,0.6,0.7,0.9,0.65,0.9,0.5,0.4] },
  { name:"Yoriko Sasaki", film:"El recuerdo de Marnie (2014)", image:IMG("Yoriko"), desc:"Madre adoptiva de Anna. Amor que se demuestra en cuidados cotidianos y en saber esperar.", quote:"Aquí estaré cuando me necesites.", vector:[0.95,0.6,0.85,0.55,0.5,0.95,0.75,0.85,0.5,0.5] },
  { name:"Los Ōiwa", film:"El recuerdo de Marnie (2014)", image:IMG("Oiwa"), desc:"Matrimonio del pueblo costero que acoge a Anna durante el verano. Hospitalidad sencilla que reconstruye mundos rotos.", quote:"Aquí estás en casa, Anna.", vector:[0.9,0.75,0.75,0.55,0.55,0.9,0.6,0.85,0.5,0.35] },

  // ─── 23. La tortuga roja (2016) ───
  { name:"El náufrago", film:"La tortuga roja (2016)", image:IMG("Naufrago"), desc:"Hombre sin nombre que llega a una isla desierta y pasa allí el resto de su vida. Tu resiliencia y respeto por lo natural transforman la soledad en comunión.", quote:"(El mar guarda las historias que no necesitan palabras.)", vector:[0.7,0.95,0.9,0.7,0.9,0.75,0.9,0.95,0.6,0.5] },
  { name:"El hijo", film:"La tortuga roja (2016)", image:IMG("Hijo Naufrago"), desc:"El niño nacido en la isla, que nada mejor que su padre y acaba marchándose con las tortugas. En tu juventud se cumple el ciclo de la vida.", quote:"(Nada mar adentro sin mirar atrás.)", vector:[0.8,1.0,0.85,0.85,0.9,0.8,0.85,0.85,0.6,0.35] },
  { name:"La mujer", film:"La tortuga roja (2016)", image:IMG("Mujer Tortuga"), desc:"La tortuga roja que impide la huida del náufrago y que después sale de su caparazón convertida en mujer. Amor que trasciende forma y tiempo.", quote:"(Aparece desnuda en la orilla, mirándolo.)", vector:[0.85,1.0,0.8,0.6,0.95,0.9,0.7,0.9,0.5,0.6] },
  { name:"Los cangrejos", film:"La tortuga roja (2016)", image:IMG("Cangrejos"), desc:"Colonia de cangrejos que habita la playa de la isla. Testigos pequeños de una vida entera.", quote:"(Su trajín incesante sobre la arena.)", vector:[0.5,0.95,0.8,0.7,0.6,0.7,0.7,0.85,0.4,0.3] },

  // ─── 24. Earwig y la bruja (2020) ───
  { name:"Earwig", film:"Earwig y la bruja (2020)", image:IMG("Earwig"), desc:"Niña de diez años que consigue que todos los adultos hagan lo que ella quiere. Astucia luminosa que transforma su prisión en hogar.", quote:"Siempre consigo lo que quiero, ¿sabes?", vector:[0.7,0.5,0.85,0.9,0.6,0.7,0.9,0.6,0.9,0.55] },
  { name:"Bella Yaga", film:"Earwig y la bruja (2020)", image:IMG("Bella Yaga"), desc:"Bruja que adopta a Earwig para tener un par de manos gratis. Rudeza de oficio que esconde una soledad aprendida a golpes.", quote:"¡A trabajar! Aquí no hay sitio para holgazanes.", vector:[0.4,0.4,0.85,0.65,0.7,0.6,0.9,0.55,0.7,0.75] },
  { name:"Mandrágora", film:"Earwig y la bruja (2020)", image:IMG("Mandragora"), desc:"Demonio enorme que vive con Bella Yaga y al que no se puede molestar. Fuerza dormida que solo responde a la astucia.", quote:"¡No me despiertes si no quieres que me enfade!", vector:[0.3,0.3,0.85,0.5,0.6,0.5,0.85,0.4,0.5,0.85] },
  { name:"Thomas", film:"Earwig y la bruja (2020)", image:IMG("Thomas"), desc:"Gato negro que habla, familiar de Bella Yaga y único aliado de Earwig. Ironía y sabiduría felina al servicio de la niña.", quote:"Puedo hablar, pero no siempre quiero.", vector:[0.75,0.5,0.75,0.85,0.6,0.9,0.85,0.7,0.8,0.55] },
  { name:"Custard", film:"Earwig y la bruja (2020)", image:IMG("Custard"), desc:"Niño del orfanato de Saint Morwald y único amigo de Earwig. Lealtad callada que no pide nada a cambio.", quote:"(Le pasa un dibujo hecho a escondidas.)", vector:[0.9,0.5,0.7,0.7,0.5,0.95,0.6,0.7,0.65,0.4] },
  { name:"La directora del orfanato", film:"Earwig y la bruja (2020)", image:IMG("Directora"), desc:"Responsable de Saint Morwald, donde Earwig pasa sus primeros diez años. Rigidez institucional ante la chispa de una niña.", quote:"Aquí las niñas deben ser obedientes.", vector:[0.4,0.3,0.85,0.5,0.4,0.6,0.85,0.6,0.4,0.7] },
  { name:"La madre de Earwig", film:"Earwig y la bruja (2020)", image:IMG("Madre Earwig"), desc:"Bruja y cantante de la banda Earwig, que deja a su hija en un orfanato. Amor libre que no sabe quedarse.", quote:"¡La música me llama, pequeña!", vector:[0.5,0.4,0.75,0.8,0.7,0.5,0.95,0.4,0.85,0.75] },

  // ─── 25. El chico y la garza (2023) ───
  { name:"Mahito Maki", film:"El chico y la garza (2023)", image:IMG("Mahito"), desc:"Chico de once años que baja a otro mundo tras la muerte de su madre. Aprendes que la pérdida puede abrir puertas a mundos que no imaginabas.", quote:"Debo encontrar lo que he perdido.", vector:[0.8,0.6,0.75,0.8,0.85,0.85,0.75,0.6,0.85,0.75] },
  { name:"La Garza Real", film:"El chico y la garza (2023)", image:IMG("Garza"), desc:"Guía y embustero, mitad ave mitad hombre, que arrastra a Mahito hasta la torre. Tus palabras, a veces incómodas, abren caminos necesarios.", quote:"Todo lo que buscas te está esperando del otro lado.", vector:[0.65,0.5,0.75,0.85,0.9,0.7,0.85,0.55,0.9,0.7] },
  { name:"Natsuko", film:"El chico y la garza (2023)", image:IMG("Natsuko"), desc:"Hermana menor de la madre de Mahito, nueva esposa de su padre y embarazada. Tu amor constante sostiene a quienes atraviesan la tormenta.", quote:"Estoy aquí, Mahito. No estás solo.", vector:[0.9,0.6,0.85,0.6,0.7,0.9,0.7,0.85,0.7,0.5] },
  { name:"Himi", film:"El chico y la garza (2023)", image:IMG("Himi"), desc:"Chica que domina el fuego en el mundo de la torre. Fuego que protege y quema: la fuerza de lo femenino en su forma más pura.", quote:"(Enciende una llama con las manos.)", vector:[0.85,0.7,0.9,0.8,0.85,0.85,0.85,0.7,0.85,0.5] },
  { name:"Kiriko", film:"El chico y la garza (2023)", image:IMG("Kiriko"), desc:"Una de las siete ancianas de la casa; marinera y pescadora en el mundo inferior. Fuerza femenina que sostiene la travesía.", quote:"¡Aquí se pesca y se navega, no se sueña!", vector:[0.85,0.75,0.9,0.75,0.6,0.9,0.85,0.7,0.6,0.4] },
  { name:"El tío abuelo", film:"El chico y la garza (2023)", image:IMG("Tio abuelo"), desc:"Creador y sostenedor del mundo de la torre; antepasado desaparecido de la familia. En tus bloques de piedra se mide el peso de crear mundos.", quote:"Construye con cuidado. Todo lo que hagas, vivirá.", vector:[0.6,0.6,0.85,0.9,0.9,0.7,0.9,0.85,0.95,0.6] },
  { name:"Warawara", film:"El chico y la garza (2023)", image:IMG("Warawara"), desc:"Almas blancas que suben desde el mundo inferior para nacer en el de arriba. La promesa de toda vida que está por venir.", quote:"(Flotan hacia la luz sin miedo.)", vector:[0.85,0.7,0.75,0.85,0.95,0.7,0.75,0.9,0.7,0.3] },
  { name:"Rey Periquito", film:"El chico y la garza (2023)", image:IMG("Rey Periquito"), desc:"Soberano de los periquitos carnívoros que han colonizado el mundo de la torre. La parodia del poder absoluto.", quote:"¡Esta tierra es nuestra por derecho!", vector:[0.2,0.3,0.85,0.6,0.5,0.4,0.95,0.4,0.5,0.85] },
  { name:"Shōichi Maki", film:"El chico y la garza (2023)", image:IMG("Shoichi Maki"), desc:"Industrial de la aviación, padre de Mahito y viudo de Hisako. Amor torpe de quien construye aviones pero no sabe hablar con su hijo.", quote:"Pronto volveremos a casa, Mahito.", vector:[0.6,0.4,0.85,0.65,0.5,0.8,0.9,0.6,0.7,0.65] }
